-- Daily challenges for 2026-10-30: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-30. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('getting-back-to-a-hobby-you-loved', 'Getting Back to a Hobby You Loved', 'For anyone who has let a favorite pastime slip away under work, family or a busy season. Each day is one small step back toward it, from dusting off the gear to finding ten minutes and enjoying being a little rusty.', 'Creativity', 365, array['Self-Care', 'Motivation', 'Goals']::text[], 1, '2026-10-30T17:00:00+00:00'::timestamptz),
  ('finding-meaning-in-your-work', 'Finding Meaning in Your Work', 'For anyone whose work, paid or unpaid, has started to feel like just a list of tasks. Each day is one small way to notice who your work helps, take pride in doing it well and connect it to what you care about.', 'Work', 365, array['Work', 'Values', 'Motivation']::text[], 1, '2026-10-30T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('getting-back-to-a-hobby-you-loved', 'finding-meaning-in-your-work');

